layer_change_gcode:
G92 E0
; update layer progress
M73 L{layer_num+1}

before_layer_change_gcode:
TIMELAPSE_TAKE_FRAME
; before layer [layer_num] change
{if layer_z <= initial_layer_print_height + layer_height * 2}
M140 S{max(bed_temperature_initial_layer_single, bed_temperature_initial_layer_single)}
{else}
M140 S{max(bed_temperature[0], bed_temperature[1])}
{endif}
{if layer_z == initial_layer_print_height + layer_height * 1 }
{if(is_extruder_used[0] == true)}M104 T0 S{nozzle_temperature[0]} ; raise extruder one temp{endif}
{if(is_extruder_used[1] == true)}M104 T1 S{nozzle_temperature[1]} ; raise extruder two temp{endif}

{endif}
{if (filament_type[0] =="PLA" or filament_type[0] =="PETG")}
{if layer_z >= initial_layer_print_height + layer_height * 2}
M106 P2 S150
{elsif layer_z >= initial_layer_print_height + layer_height * 1}
M106 P2 S100
{else}
M106 P2 S0
{endif}
{endif}
G92 E0

layer_change_gcode:
G92 E0
; update layer progress
M73 L{layer_num+1}
